mapper.select:
SELECT COUNT(id) AS count, auth_status AS tabFlag FROM transfer_logistics_supplier ls WHERE is_deleted=FALSE
${permissionSql}
GROUP BY auth_status

SELECT id, create_user_name AS createUserName, create_time AS createTime , update_user_name AS updateUserName, update_time AS updateTime, supplier_id AS supplierId , supplier_name AS name, disabled , auth_status AS authStatus , auth_time AS authTime FROM transfer_logistics_supplier ls WHERE is_deleted=FALSE
AND ls.auth_status = #{params.tabFlag}
AND ls.supplier_name ILIKE concat('%',#{params.name}::text,'%')
AND ls.create_user_id IN
#{item}
AND ls.auth_status IN
#{item}
AND ls.disabled IN
#{item}
AND ls.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ls.create_time
AND ls.update_time >= #{params.updateTimeList[0]} and (#{params.updateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ls.update_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ls.create_time DESC

