and ls.id in
#{item}
AND ls.supplier_name ILIKE concat('%',#{params.name}::text,'%')
AND ls.create_user_id IN
#{item}
AND ls.auth_status IN
#{item}
AND ls.disabled IN
#{item}
AND ls.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ls.create_time
AND ls.update_time >= #{params.updateTimeList[0]} and (#{params.updateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ls.update_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ls.create_time DESC

SELECT tls.id, tla.id AS authId, tla.main_id AS mainId, tls.supplier_id, tls.supplier_name, tls.auth_status, tls.disabled, tla.logistics_platform FROM transfer_logistics_supplier tls INNER JOIN transfer_logistics_auth tla ON tls.id = tla.main_id AND tla.is_deleted=FALSE WHERE tls.is_deleted=FALSE
AND tls.id IN
#{item}
